import AppKit

/// Plays the bundled chiptune "cock-a-doodle-doo" (Latch/Resources/crow.wav,
/// generated by tools/make-crow-sound.swift).
enum CrowSoundPlayer {

    private static let sound: NSSound? = {
        guard let url = Bundle.main.url(forResource: "crow", withExtension: "wav") else { return nil }
        return NSSound(contentsOf: url, byReference: true)
    }()

    static func play() {
        guard let sound else { return }
        if sound.isPlaying { sound.stop() }
        sound.play()
    }
}
